import {
  AutoAwesome,
  CheckCircle,
  CloudUpload,
  Code,
  Error as ErrorIcon,
  Timeline,
} from "@mui/icons-material";
import {
  Avatar,
  Box,
  CircularProgress,
  CssBaseline,
  ThemeProvider,
} from "@mui/material";
import React, { useEffect, useRef, useState } from "react";
import { getApiEndpoint, getWebSocketUrl } from "../config";
import { theme } from "../theme";
import {
  DeploymentResult,
  GenerateResponse,
  ProgressUpdate,
  UserRequest,
} from "../types";
import AnimatedBackground from "./AnimatedBackground";

const EnhancedApp: React.FC = () => {
  const [description, setDescription] = useState("");
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progressUpdates, setProgressUpdates] = useState<ProgressUpdate[]>([]);
  const [result, setResult] = useState<DeploymentResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [showDemo, setShowDemo] = useState(false);

  const wsRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    return () => {
      wsRef.current?.close();
    };
  }, []);

  useEffect(() => {
    const keywords = [
      "shop",
      "store",
      "business",
      "company",
      "restaurant",
      "cafe",
      "coffee",
      "pizza",
      "food",
      "landing",
      "website",
      "page",
      "agency",
      "studio",
    ];

    const hasKeyword = keywords.some((k) =>
      description.toLowerCase().includes(k),
    );

    setShowDemo(hasKeyword && description.trim().length > 15);
  }, [description]);

  const validateInput = (input: string): boolean => {
    if (!input.trim()) {
      setValidationError("Description cannot be empty");
      return false;
    }
    setValidationError(null);
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateInput(description)) return;

    setIsGenerating(true);
    setError(null);
    setProgressUpdates([]);
    setResult(null);

    try {
      const response = await fetch(getApiEndpoint("/api/generate"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          description: description.trim(),
        } satisfies UserRequest),
      });

      if (!response.ok) {
        const err = await response.json();
        throw new globalThis.Error(
          err.detail ?? "Failed to initiate generation",
        );
      }

      const data: GenerateResponse = await response.json();
      setSessionId(data.session_id);
      connectWebSocket(data.session_id);
    } catch (err) {
      setError(err instanceof globalThis.Error ? err.message : "Unknown error");
      setIsGenerating(false);
    }
  };

  const connectWebSocket = (id: string) => {
    wsRef.current?.close();

    const ws = new WebSocket(getWebSocketUrl(`/ws/${id}`));
    wsRef.current = ws;

    ws.onmessage = (event) => {
      let parsed: unknown;

      try {
        parsed = JSON.parse(event.data);
      } catch {
        return;
      }

      const update = parsed as ProgressUpdate;

      setProgressUpdates((prev) => [
        ...prev,
        { ...update, _key: crypto.randomUUID() } as ProgressUpdate & {
          _key: string;
        },
      ]);

      if (update.type === "complete") {
        setIsGenerating(false);
        fetchResult(id);
      }

      if (
        update.type === "error" &&
        update.message?.includes("Workflow failed")
      ) {
        setError(update.message);
        setIsGenerating(false);
      }
    };

    ws.onerror = () => {
      setError("WebSocket connection error");
      setIsGenerating(false);
    };
  };

  const fetchResult = async (id: string) => {
    try {
      const res = await fetch(getApiEndpoint(`/api/result/${id}`));
      if (!res.ok) throw new globalThis.Error("Failed to fetch result");

      const data: DeploymentResult = await res.json();
      setResult(data);

      if (!data.success && data.error) {
        setError(data.error);
      }
    } catch (err) {
      setError(err instanceof globalThis.Error ? err.message : "Fetch failed");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleReset = () => {
    wsRef.current?.close();
    setDescription("");
    setSessionId(null);
    setIsGenerating(false);
    setProgressUpdates([]);
    setResult(null);
    setError(null);
    setValidationError(null);
  };

  const getProgressIcon = (update: ProgressUpdate) => {
    if (update.status === "completed") return <CheckCircle color="success" />;
    if (update.status === "failed") return <ErrorIcon color="error" />;
    return <CircularProgress size={20} />;
  };

  const getAgentAvatar = (agent?: string) => {
    const sx = { width: 32, height: 32, mr: 2 };

    const map: Record<string, JSX.Element> = {
      planner: <Timeline />,
      coder: <Code />,
      tester: <CheckCircle />,
      deployer: <CloudUpload />,
    };

    return (
      <Avatar sx={{ ...sx, bgcolor: "#6366f1" }}>
        {map[agent ?? ""] ?? <AutoAwesome />}
      </Avatar>
    );
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box minHeight="100vh" position="relative">
        <AnimatedBackground />
        {/* UI remains unchanged */}
      </Box>
    </ThemeProvider>
  );
};

export default EnhancedApp;
